CATBoolean CmdLuaRunner::RunAction(void *data1)
{
	//获取模块所在目录（win_b64/code/bin）
	TCHAR szModPath[MAX_PATH] = L"";
	HMODULE hMod = GetModuleHandle(L"CatiaLuaCmd.dll");
	if (hMod != NULL)
	{
		GetModuleFileName(hMod, szModPath, MAX_PATH);
		WCHAR* str = wcsrchr(szModPath, L'\\');
		if (str != NULL) *str = L'\0';
	}
	//脚本路径：win_b64\CustomData\main.lua
	CATUnicodeString sScriptDir = NULL;
	sScriptDir.BuildFromWChar(szModPath);
	sScriptDir = sScriptDir + "\\..\\..\\CustomData";
	CATUnicodeString sScriptPath = sScriptDir + "\\main.lua";

	//脚本不存在则生成示例
	if (_access(sScriptPath.ConvertToChar(), 0) == -1)
	{
		ofstream oFile;
		oFile.open(sScriptPath.ConvertToChar());
		oFile << "-- CatiaLua sample script" << endl;
		oFile << "function main()" << endl;
		oFile << "    print(\"Hello from LuaEngine!\")" << endl;
		oFile << "end" << endl;
		oFile.close();
	}

	//执行 Lua 脚本
		LuaEngine* pEngine = LuaEngine::GetInstance();
	if (!pEngine->Init())
	{
		MessageBox(NULL, L"Lua 引擎初始化失败：", L"提示", MB_OK | MB_ICONINFORMATION);
		return FALSE;
	}
	if (!pEngine->LoadScriptFile(sScriptPath.ConvertToChar()))
	{
		wchar_t* Utf8ToWchar(const char* cstr);   // forward decl (defined below)
		wchar_t* wszErr = Utf8ToWchar(pEngine->GetLastError());
		std::wstring sErrMsg = L"加载脚本失败：";
		if (wszErr != NULL) sErrMsg += wszErr;
		if (wszErr != NULL) delete[] wszErr;
		MessageBox(NULL, sErrMsg.c_str(), L"提示", MB_OK | MB_ICONINFORMATION);
		return FALSE;
	}
	if (!pEngine->RunFunction("main"))
	{
		wchar_t* Utf8ToWchar(const char* cstr);   // forward decl (defined below)
		wchar_t* wszErr = Utf8ToWchar(pEngine->GetLastError());
		std::wstring sErrMsg = L"执行 main 失败：";
		if (wszErr != NULL) sErrMsg += wszErr;
		if (wszErr != NULL) delete[] wszErr;
		MessageBox(NULL, sErrMsg.c_str(), L"提示", MB_OK | MB_ICONINFORMATION);
		return FALSE;
	}
	MessageBox(NULL, L"Lua 脚本执行成功：", L"提示", MB_OK | MB_ICONINFORMATION);
	return TRUE;
}


wchar_t* Utf8ToWchar(const char* cstr)
{
	//uft8转宽字节
	unsigned int nLen = MultiByteToWideChar(CP_UTF8, NULL, cstr, -1, NULL, NULL);
	wchar_t *wszBuffer = new wchar_t[nLen + 1];
	nLen = MultiByteToWideChar(CP_UTF8, NULL, cstr, -1, wszBuffer, nLen);
	wszBuffer[nLen] = 0;
	return wszBuffer;
}

char* WcharToChar(const wchar_t* wcstr)
{
	char *m_char;
	int len = WideCharToMultiByte(CP_ACP, 0, wcstr, wcslen(wcstr), NULL, 0, NULL, NULL);
	m_char = new char[len + 1];
	WideCharToMultiByte(CP_ACP, 0, wcstr, wcslen(wcstr), m_char, len, NULL, NULL);
	m_char[len] = '\0';
	return m_char;
}

char* Utf8ToMultibyte(const char* cstr)
{
	//uft8转宽字节
	wchar_t *wszBuffer = Utf8ToWchar(cstr);
	//宽字节转多字节
	char* m_char = WcharToChar(wszBuffer);
	delete[] wszBuffer;
	return m_char;
}



